static double field_difference(const struct field *a,const struct field *b){double n=0.0,d=0.0,x;int k;for(k=0;k<a->nrows*a->ncols;++k){x=(double)a->data[k]-b->data[k];n+=x*x;d+=(double)b->data[k]*b->data[k];}return sqrt(n/fmax(d,1e-300));}
static double volume_difference(const struct volume *a,const struct volume *b){double n=0.0,d=0.0,x;int i,j,l;for(j=a->rmin;j<=a->rmax;++j)for(i=a->cmin;i<=a->cmax;++i)for(l=1;l<=a->mechanisms;++l){x=(double)a->v[j][i][l]-b->v[j][i][l];n+=x*x;d+=(double)b->v[j][i][l]*b->v[j][i][l];}return sqrt(n/fmax(d,1e-300));}
static double state_difference(const struct owned_state *a,const struct owned_state *b){double m=0.0;m=fmax(m,field_difference(&a->vz,&b->vz));m=fmax(m,field_difference(&a->sxz,&b->sxz));m=fmax(m,field_difference(&a->syz,&b->syz));m=fmax(m,volume_difference(&a->r,&b->r));m=fmax(m,volume_difference(&a->q,&b->q));if(FW){m=fmax(m,field_difference(&a->psi_sxz_x,&b->psi_sxz_x));m=fmax(m,field_difference(&a->psi_syz_y,&b->psi_syz_y));m=fmax(m,field_difference(&a->psi_vzx,&b->psi_vzx));m=fmax(m,field_difference(&a->psi_vzy,&b->psi_vzy));}return m;}
