static struct dgrad_field dg_new(void){struct dgrad_field f;int j;f.rows=(double **)calloc((size_t)NY+2,sizeof(double *));f.data=(double *)calloc((size_t)(NX+2)*(NY+2),sizeof(double));if(!f.rows||!f.data)MPI_Abort(MPI_COMM_WORLD,801);f.v=f.rows;for(j=0;j<=NY+1;++j)f.v[j]=f.data+(size_t)j*(NX+2);return f;}
